/**
 * Jinx Lord of Typhon + Summoner: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Lord_of_Typhon
 * Wiki: https://wiki.bloodontheclocktower.com/Summoner
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L118). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { neighbourBecoming, ownJinxRules } from '#lib/core/rules/jinxes.ts';
import { scenario } from '#lib/core/testing/scenario.ts';
import { scriptOf } from './summoner.test-support.ts';

describe('Lord of Typhon + Summoner jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'lordoftyphon', 'summoner');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('lordoftyphon')?.name).toBe('Lord of Typhon');
		expect(data.byId.get('summoner')?.name).toBe('Summoner');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['lordoftyphon', 'summoner'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['lordoftyphon'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['summoner'])).not.toContain(jinx);
	});

	const ids = ['summoner', 'lordoftyphon', 'poisoner', 'spy', 'chef', 'empath', 'monk', 'saint'];
	// Seated in a circle: the Summoner, Poisoner, Chef, Empath, Monk and Saint.
	const base = scenario(['summoner', 'poisoner', 'chef', 'empath', 'monk', 'saint'], {
		script: scriptOf(ids)
	});
	const near = (s: typeof base, seat: string) =>
		neighbourBecoming(s.game, 'summoner', 'lordoftyphon', s.seat(seat), s.characters);

	describe('a summoned Lord of Typhon neighbours a Minion, and the other neighbour becomes one', () => {
		it("is data in the Summoner's rules", () => {
			// Wiki: "If a Lord of Typhon is summoned, they must neighbor a Minion & their other neighbor becomes an evil Minion."
			expect(ownJinxRules(base.game, 'summoner', 'lordoftyphon', base.characters)).toEqual({
				neighbourBecomes: 'minion'
			});
		});

		it('makes the other neighbour of a player beside a Minion an evil Minion', () => {
			// Wiki: "their other neighbor becomes an evil Minion."
			expect(near(base, 'chef')).toEqual({
				type: 'minion',
				fits: true,
				becomes: base.seat('empath')
			});
		});

		it('says a player beside no Minion does not fit', () => {
			// Wiki: "they must neighbor a Minion"
			expect(near(base, 'monk')).toEqual({ type: 'minion', fits: false });
		});

		it('skips dead players, as neighbours are the nearest living ones', () => {
			// Wiki: "they must neighbor a Minion"
			const s = base.dies('chef');
			expect(near(s, 'empath')).toEqual({
				type: 'minion',
				fits: true,
				becomes: s.seat('monk')
			});
		});

		it('asks nothing of any other Demon', () => {
			// Wiki: "If a Lord of Typhon is summoned"
			expect(
				neighbourBecoming(base.game, 'summoner', 'imp', base.seat('chef'), base.characters)
			).toBe(undefined);
		});
	});
});
